#include "Mapper105.h"
#include "../state_io.h"
#include <algorithm>
void Mapper105::reset(){shiftReg=0x10;shiftCount=0;control=0x1C;chr0=0x10;chr1=0;prgReg=0;mirrorMode=3;initState=0;irqCounter=0;irqEnabled=irqActive=false;updateState();}
void Mapper105::updateState(){uint8_t m=control&3u;mirrorMode=m==0?3u:m==1?4u:m==2?1u:0u;if(initState==0&&!(chr0&0x10u))initState=1;else if(initState==1&&(chr0&0x10u))initState=2;if(chr0&0x10u){irqEnabled=false;irqCounter=0;irqActive=false;}else irqEnabled=true;}
void Mapper105::commit(uint16_t a,uint8_t v){v&=0x1Fu;if(a<0xA000u)control=v;else if(a<0xC000u)chr0=v;else if(a<0xE000u)chr1=v;else prgReg=v;updateState();}
uint16_t Mapper105::selectedPrg16(uint16_t a)const{if(initState!=2)return uint16_t((a>=0xC000u)?1u:0u);if(chr0&8u){uint16_t p=uint16_t((prgReg&7u)|8u);if(control&8u){if(control&4u)return a<0xC000u?p:0x0Fu;return a<0xC000u?8u:p;}uint16_t base=uint16_t(p&0x0Eu);return uint16_t(base+(a>=0xC000u));}uint16_t base=uint16_t(chr0&6u);return uint16_t(base+(a>=0xC000u));}
bool Mapper105::cpuMapRead(uint16_t a,uint32_t&m){if(a>=0x6000u&&a<=0x7FFFu){if(prgReg&0x10u)return false;m=PRG_RAM_FLAG|uint32_t(a&0x1FFFu);return true;}if(a<0x8000u)return false;uint16_t c=std::max<uint16_t>(1,prgBanks);m=uint32_t(selectedPrg16(a)%c)*0x4000u+(a&0x3FFFu);return true;}
bool Mapper105::cpuMapWrite(uint16_t a,uint32_t&m,uint8_t d){if(a>=0x6000u&&a<=0x7FFFu){if(!(prgReg&0x10u)){m=PRG_RAM_FLAG|uint32_t(a&0x1FFFu);return true;}m=0;return true;}if(a<0x8000u)return false;if(d&0x80u){shiftReg=0x10;shiftCount=0;control|=0x0Cu;updateState();m=0;return true;}shiftReg=uint8_t((shiftReg>>1)|((d&1u)<<4));if(++shiftCount==5){commit(a,shiftReg);shiftReg=0x10;shiftCount=0;}m=0;return true;}
bool Mapper105::ppuMapRead(uint16_t a,uint32_t&m){if(a>0x1FFFu)return false;if(control&0x10u){uint16_t p=a<0x1000u?chr0:chr1;uint16_t c=std::max<uint16_t>(1,chrBanks?uint16_t(chrBanks*2u):2u);m=uint32_t(p%c)*0x1000u+(a&0x0FFFu);}else{uint16_t p=uint16_t((chr0&0x1Eu)>>1);uint16_t c=std::max<uint16_t>(1,chrBanks);m=uint32_t(p%c)*0x2000u+a;}return true;}
bool Mapper105::ppuMapWrite(uint16_t a,uint32_t&m,uint8_t){return chrBanks==0&&ppuMapRead(a,m);}
void Mapper105::cpuClock(){if(irqEnabled){++irqCounter;uint32_t max=0x20000000u|(uint32_t(dipSwitches&0x0Fu)<<25);if(irqCounter>=max){irqActive=true;irqEnabled=false;}}}
void Mapper105::saveState(std::vector<uint8_t>&o)const{using namespace ciphernes_state;write_u8(o,shiftReg);write_u8(o,shiftCount);write_u8(o,control);write_u8(o,chr0);write_u8(o,chr1);write_u8(o,prgReg);write_u8(o,mirrorMode);write_u8(o,initState);write_u8(o,dipSwitches);write_u32(o,irqCounter);write_bool(o,irqEnabled);write_bool(o,irqActive);}bool Mapper105::loadState(const uint8_t*&p,const uint8_t*e){using namespace ciphernes_state;return read_u8(p,e,shiftReg)&&read_u8(p,e,shiftCount)&&read_u8(p,e,control)&&read_u8(p,e,chr0)&&read_u8(p,e,chr1)&&read_u8(p,e,prgReg)&&read_u8(p,e,mirrorMode)&&read_u8(p,e,initState)&&read_u8(p,e,dipSwitches)&&read_u32(p,e,irqCounter)&&read_bool(p,e,irqEnabled)&&read_bool(p,e,irqActive);}
